    {
        context |= HandshakeOptions.X64;
    }
    if (clrVersion == 2)
    {
        context |= HandshakeOptions.CLR2;
    }
    if (nodeReuse)
    {
        context |= HandshakeOptions.NodeReuse;
    }
    if (lowPriority)
    {
        context |= HandshakeOptions.LowPriority;
    }

    return $"MSBuild.RAR.{userName}.{(int)context}";
}

